<div class="page-heading"><div><p class="eyebrow">SHOP INVENTORY CONFIGURATION</p><h1><?= e($title) ?></h1></div></div>
<section class="card floating-card" data-card-key="inventory-form-<?= e($resource) ?>"><h2 class="floating-label"><span class="material-symbols-rounded" aria-hidden="true">inventory_2</span><?= e(ucwords(str_replace('-',' ',$resource))) ?> details</h2><div class="card-body">
<form action="/inventory/<?= e($resource) ?>/<?= $record?e($record['id']) . '/edit':'add' ?>" method="post" data-ajax-form><?= csrf() ?>
<label class="form-label">Name<input class="form-control mb-3" name="name" value="<?= e($record['name'] ?? '') ?>" required maxlength="160"></label>
<?php if ($resource==='category'): ?><label class="form-label">Parent category (leave blank for a top-level category)<select class="form-select mb-3" name="parent_id"><option value="">Top-level category</option><?php foreach (array_filter($folders,fn(array $f): bool => $f['parent_id']===null) as $folder): ?><option value="<?= e($folder['id']) ?>" <?= ($record['parent_id'] ?? null)===$folder['id']?'selected':'' ?>><?= e($folder['name']) ?></option><?php endforeach; ?></select></label>
<?php elseif ($resource==='item-type'): ?><label class="form-label">Subcategory<select class="form-select mb-3" name="folder_id" required><option value="">Select subcategory...</option><?php foreach (array_filter($folders,fn(array $f): bool => $f['parent_id']!==null) as $folder): ?><option value="<?= e($folder['id']) ?>" <?= ($record['folder_id'] ?? null)===$folder['id']?'selected':'' ?>><?= e($folder['parent_name']) ?> / <?= e($folder['name']) ?></option><?php endforeach; ?></select></label><label class="form-label">Unique asset prefix<input class="form-control mb-3" name="prefix" value="<?= e($record['prefix'] ?? '') ?>" maxlength="24" placeholder="S4" pattern="[A-Za-z0-9]+(?:-[A-Za-z0-9]+)*" required></label>
<?php elseif ($resource==='package'): ?><label class="form-label">Package description<textarea class="form-control mb-3" name="description" rows="3" maxlength="10000"></textarea></label><p>Each quantity is the component ratio for one package. Only item-type components are allowed; nested packages cannot create circular dependencies.</p><?php require ROOT . '/app/Views/partials/line-editor.php'; ?>
<?php else: ?><div class="form-grid"><?php foreach (['source'=>'Source equipment','dependency'=>'Required accessory'] as $prefix=>$label): ?><label class="form-label"><?= e($label) ?><select class="form-select mb-3" name="<?= e($prefix) ?>_type_id" required><option value="">Select equipment...</option><?php foreach ($types as $type): ?><option value="<?= e($type['id']) ?>"><?= e($type['name']) ?></option><?php endforeach; ?></select></label><label class="form-label"><?= e($prefix==='source'?'For every quantity of source':'Require quantity of accessory') ?><input class="form-control mb-3" type="number" name="<?= e($prefix) ?>_quantity" min="1" max="1000000" value="1" required></label><?php endforeach; ?></div>
<label class="form-label">Enforcement<select class="form-select mb-3" name="mode"><option value="warning">Warning - advisory validation</option><option value="strict">Strict - block invalid requests and pulls</option></select></label><p class="text-secondary">Create multiple rules for an item to express multiple accessory dependencies.</p><?php endif; ?>
<div class="form-error" role="alert" hidden></div><button class="btn btn-primary mt-3">Save <?= e(str_replace('-',' ',$resource)) ?></button></form></div></section>
<?php if ($record): ?><section class="card floating-card" data-card-key="inventory-delete"><h2 class="floating-label">Remove unused record</h2><div class="card-body"><p>Only empty categories and unused item types can be deleted. Historical records and serialized assets are protected.</p><form action="/inventory/<?= e($resource) ?>/<?= e($record['id']) ?>/delete" method="post" data-ajax-form data-confirm="Delete this unused inventory record?"><?= csrf() ?><div class="form-error" role="alert" hidden></div><button class="btn btn-outline-danger">Delete unused record</button></form></div></section><?php endif; ?>
